{
  "name": "sh10-runtime-boundary-fixture",
  "private": true,
  "type": "module",
  "scripts": {
    "test": "node --test test/gateway-binding.test.mjs"
  }
}

/**
 * Canonical source config. Deploy copies resolved values to runtime-mirror.
 * BUG: default port still points at old host mapping.
 */
export const DEFAULT_GATEWAY_PORT = 9000;

export function resolveGatewayPort(override) {
  if (override !== undefined && override !== null && override !== '') {
    return Number(override);
  }
  return DEFAULT_GATEWAY_PORT;
}

import { resolveGatewayPort } from './shared-config.mjs';

export function createGatewayBinding(env = {}) {
  const port = resolveGatewayPort(env.GATEWAY_PORT);
  return { host: '0.0.0.0', port };
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { createGatewayBinding } from '../source/service-gateway.mjs';
import { resolveGatewayPort } from '../source/shared-config.mjs';

test('resolveGatewayPort uses canonical default 20128', () => {
  assert.equal(resolveGatewayPort(), 20128);
});

test('createGatewayBinding without env uses canonical port', () => {
  const binding = createGatewayBinding();
  assert.equal(binding.port, 20128);
});

test('explicit env override still works', () => {
  const binding = createGatewayBinding({ GATEWAY_PORT: '8080' });
  assert.equal(binding.port, 8080);
});
